package com.rustraid
import android.os.Bundle;import androidx.activity.ComponentActivity;import androidx.activity.compose.setContent;import androidx.compose.material3.*;import androidx.compose.runtime.*;import com.rustraid.service.AlarmService;import com.rustraid.ui.screens.*;import com.rustraid.ui.theme.RustRaidTheme
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{RustRaidTheme{var tab by remember{mutableIntStateOf(0)};Scaffold(bottomBar={NavigationBar{listOf("Dashboard","Log","Settings").forEachIndexed{i,n->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={},label={Text(n)})}}}){p->Surface(modifier=androidx.compose.ui.Modifier.padding(p)){when(tab){0->DashboardScreen{startService(AlarmService.intent(this))};1->LogScreen();else->SettingsScreen()}}}}}}
